-- Synthetic local/development rollback suite. No email delivery or Storage objects.
begin;
create temp table sa_checks(name text primary key);grant select,insert on sa_checks to authenticated,anon;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAILED %',label;end if;insert into pg_temp.sa_checks values(label);end$$;
create function pg_temp.denied(sql text,code text,label text) returns void language plpgsql as $$declare caught text;begin begin execute sql;exception when others then get stacked diagnostics caught=returned_sqlstate;end;perform pg_temp.ok(caught is not distinct from code,label||coalesce(' ['||caught||']',' [no error]'));end$$;
create function pg_temp.claim(n integer) returns void language sql as $$select set_config('request.jwt.claims',jsonb_build_object('iss','https://gmvouqgjbtbkbhrdruzu.supabase.co/auth/v1','aud','authenticated','role','authenticated','sub','10000000-0000-0000-0000-'||lpad(n::text,12,'0'))::text,true)::void$$;
